from google.cloud import translate

def translate_text(text: str, target_language: str, source_language: str | None = None) -> str:
    client = translate.TranslationServiceClient()
    project_id = "YOUR_GOOGLE_CLOUD_PROJECT_ID"  # Replace with your Google Cloud Project ID
    parent = f"projects/{project_id}/locations/global"

    if source_language:
        response = client.translate_text(
            request={
                "parent": parent,
                "contents": [text],
                "mime_type": "text/plain",
                "source_language_code": source_language,
                "target_language_code": target_language,
            }
        )
    else:
        response = client.translate_text(
            request={
                "parent": parent,
                "contents": [text],
                "mime_type": "text/plain",
                "target_language_code": target_language,
            }
        )

    return response.translations[0].translated_text

import google.generativeai as genai
import os

class LLMClient:
    _instance = None

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super(LLMClient, cls).__new__(cls)
            cls._instance._configure()
        return cls._instance

    def _configure(self):
        api_key = os.getenv("GEMINI_API_KEY")
        if not api_key:
            raise ValueError("GEMINI_API_KEY environment variable not set.")
        genai.configure(api_key=api_key)

    def get_model(self, model_name: str):
        # This is a placeholder for model family selection.
        # In a real scenario, you might have different configurations for different models.
        if model_name.startswith("gemini"):
            return genai.GenerativeModel(model_name)
        else:
            raise ValueError(f"Unsupported model family: {model_name}")

def get_llm_client():
    return LLMClient()
